laravelToNextJs.instructions:
- Transpile this Laravel module into NextJS using the App Router version;
- The API call functions should be written in separate blocks (one for each HTTP method type); 
- Any API call should be wrapped into its own standalone function, and be nested into a try/catch, with the necessary imports already written;
- Follow this template example:

	export async function {NAME}(
		{FUNCTION_PARAMS}
	): Promise<{RETURN_TYPE}> {
		try {
			const res = await axios.post("{ENDPOINT}", {
				{ENDPOINT_PARAMS}
			});
			if (!res?.data)
				throw new TypeError("{ERR_MESSAGE}");
			Swal.fire({
				icon: "success",
				title: "Success",
				text: "{SUCCESS_MESSAGE}",
			});
			return null;
		} catch (e) {
			console.error(`Failed to {HTTP_METHOD} for {CONTEXT}: ${(e as Error)?.message}`);
			Swal.fire({
				icon: "error",
				title: "Error {CONTEXT}",
				text: (e as Error)?.message || "Undefined error",
			});
		}
	}
